import{_ as o,C as r,o as s,c as e,j as i,E as t,a as n,a2 as d}from"./chunks/framework.C21TwvGF.js";const q=JSON.parse('{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Cyber)","link":"/10-sinf-cyber/"},"n":3,"bob":"I-bob · Kiberxavfsizlikka kirish","lessons":[{"g":7,"title":"Xavfsizlikni anglash (2-qism): raqamli gigiyena, brauzer xavfsizligi va 2FA","lead":"Xavfsizlikni anglash tushunchasi (2-qism): raqamli gigiyena, brauzer xavfsizligi va ikki bosqichli autentifikatsiya (2FA)","link":"/10-sinf-cyber/hafta-03/dars-1","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-1-test.html"},{"g":8,"title":"Xavfsizlikni anglash (3-qism): tahdidlarni modellashtirish, Red/Blue Team va CTF","lead":"Xavfsizlikni anglash tushunchasi (3-qism): tahdidlarni modellashtirish, Red Team vs Blue Team va CTF asoslari","link":"/10-sinf-cyber/hafta-03/dars-2","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-2-test.html"},{"g":9,"title":"Tarmoq asoslari: mijoz-server arxitekturasi, topologiyalar, OSI va TCP/IP modellari","lead":"Tarmoq asoslari: mijoz-server arxitekturasi, topologiyalar, OSI va TCP/IP modellari","link":"/10-sinf-cyber/hafta-03/dars-3","slide":"/slaydlar/10-sinf-cyber/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-cyber/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-cyber/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-cyber/hafta-03/index.md","filePath":"10-sinf-cyber/hafta-03/index.md"}'),h={name:"10-sinf-cyber/hafta-03/index.md"},m={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function y(f,a,u,c,v,b){const l=r("Icon");return s(),e("div",null,[i("div",m,[i("h2",g,[t(l,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h3 id="_7-dars-raqamli-gigiyena-va-shaxsiy-kiberxavfsizlik" tabindex="-1">7-dars. Raqamli gigiyena va shaxsiy kiberxavfsizlik <a class="header-anchor" href="#_7-dars-raqamli-gigiyena-va-shaxsiy-kiberxavfsizlik" aria-label="Permalink to &quot;7-dars. Raqamli gigiyena va shaxsiy kiberxavfsizlik&quot;">​</a></h3><ol><li>O&#39;zingiz muntazam foydalanadigan brauzeringizga (Chrome, Firefox yoki Edge) <code>uBlock Origin</code> va <code>ClearURLs</code> kengaytmalarini o&#39;rnating. Har qanday 3 ta ommabop yangiliklar saytiga kirib, qancha kuzatuvchi (tracker) va reklama skriptlari bloklanganini qayd eting.</li><li>Shaxsiy kompyuteringiz yoki smartfoningizda shifrlangan xavfsiz DNS serverini (Cloudflare <code>1.1.1.1</code> yoki <code>1.1.1.2</code> zararli dasturlardan himoyalangan DNS) sozlang. Sozlash jarayonini skrinshotlar orqali hujjatlashtiring.</li><li>Telegram yoki Google hisobingizda 2-bosqichli tasdiqlash (2FA) yoqilganligini tekshiring, agar yoqilmagan bo&#39;lsa yoqing va maxfiy tiklash kodi/parolini ishonchli offline joyda saqlang.</li></ol><hr><h3 id="_8-dars-stride-tahdid-modeli-red-team-vs-blue-team-va-ctf-musobaqalari" tabindex="-1">8-dars. STRIDE tahdid modeli, Red Team vs Blue Team va CTF musobaqalari <a class="header-anchor" href="#_8-dars-stride-tahdid-modeli-red-team-vs-blue-team-va-ctf-musobaqalari" aria-label="Permalink to &quot;8-dars. STRIDE tahdid modeli, Red Team vs Blue Team va CTF musobaqalari&quot;">​</a></h3><ol><li>O&#39;zingiz bilgan bitta onlayn servis (masalan, maktab oshxonasi to&#39;lov ilovasi yoki onlayn kutubxona tizimi) uchun STRIDE modeli bo&#39;yicha tahdidlar tahlili jadvalini to&#39;ldiring: <ul><li><strong>S (Spoofing):</strong> Birov boshqa o&#39;quvchi nomidan tizimga kirish xavfi;</li><li><strong>T (Tampering):</strong> Hisobdagi balans yoki kitob ma&#39;lumotlarini o&#39;zgartirish xavfi;</li><li><strong>R (Repudiation):</strong> O&#39;tkazilgan to&#39;lov yoki olingan kitobni rad etish xavfi;</li><li><strong>I (Information Disclosure):</strong> O&#39;quvchilar telefon raqamlari yoki parollarining oqib ketishi;</li><li><strong>D (Denial of Service):</strong> Tizimni ko&#39;p so&#39;rovlar yuborib ishdan chiqarish;</li><li><strong>E (Elevation of Privilege):</strong> Oddiy o&#39;quvchining administrator huquqiga ega bo&#39;lib olishi.</li></ul></li><li>Red Team va Blue Team rollarini solishtiruvchi qisqa esse (1 sahifa) yozing: nega tashkilotlar uchun faqat himoyalanish (Blue Team) yetarli emas va doimiy mustaqil sinovlar (Red Team) talab etiladi?</li><li>CTF musobaqalarining asosiy yo&#39;nalishlari (Web, Forensics, Reverse, Pwn, Crypto) bo&#39;yicha konspekt tuzing.</li></ol><hr><h3 id="_9-dars-tarmoq-asoslari-topologiyalar-osi-modeli-va-tcp-ip-steki" tabindex="-1">9-dars. Tarmoq asoslari: topologiyalar, OSI modeli va TCP/IP steki <a class="header-anchor" href="#_9-dars-tarmoq-asoslari-topologiyalar-osi-modeli-va-tcp-ip-steki" aria-label="Permalink to &quot;9-dars. Tarmoq asoslari: topologiyalar, OSI modeli va TCP/IP steki&quot;">​</a></h3><ol><li>Yulduzsimon (Star) va To&#39;rsimon (Mesh) topologiyalarining kamida 3 tadan afzallik va kamchiliklarini taqqoslovchi jadval tuzing. Nima sababdan hozirgi zamonaviy lokal tarmoqlarda yulduzsimon topologiya keng qo&#39;llaniladi?</li><li>OSI modelining 7 ta qatlamini tartib bilan yozing va har bir qatlamda ishlaydigan kamida bittadan protokol yoki qurilmani ko&#39;rsating.</li><li>TCP va UDP protokollari o&#39;rtasidagi farqni tushuntiring: <ul><li>Nima sababdan veb-saytlarni yuklashda (HTTP/HTTPS) va fayl uzatishda TCP ishlatiladi?</li><li>Nima sababdan onlayn o&#39;yinlar, videoqo&#39;ng&#39;iroqlar va jonli efirlarda UDP afzal ko&#39;riladi?</li></ul></li><li>Kompyuteringiz terminalida <code>ping</code> va <code>traceroute</code> (yoki Windowsda <code>tracert</code>) buyruqlari orqali <code>google.com</code> yoki <code>edu.uz</code> manziliga tarmoq marshrutini tahlil qiling va natijalarni yozib oling.</li></ol><hr>',11))])])}const z=o(h,[["render",y]]);export{q as __pageData,z as default};
